<template>
  <div class="container">
    <router-link to="/catalog" class="back-btn">←</router-link>

    <div class="channel-header">
      <h1 class="channel-title">{{ group.title }}</h1>
      <div class="channel-info">
        <div class="info-row">
          <span class="info-icon">📁</span>
          <span>
            Тематика: <strong>{{ subjectNames }}</strong>
          </span>
        </div>
        <div class="info-row">
          <span class="info-icon">🌍</span>
          <span>
            Гео / Язык:
            <strong>{{ countryName }} / {{ languageName }}</strong>
          </span>
        </div>
      </div>
    </div>

    <div class="channel-visual">
      <div class="channel-logo"><div class="megaphone-icon">📢</div></div>
      <div class="channel-links">
        <div class="link-item">
          <div class="link-icon telegram-icon">✈️</div>
          <div class="link-text">
            <strong>t.me:</strong><br />
            <a :href="tgUrl" class="link-url">{{ tgUrl }}</a>
          </div>
        </div>
        <div class="link-item">
          <div class="link-icon tgstat-icon">📊</div>
          <div class="link-text">
            <strong>TGStat:</strong><br />
            <a :href="tgStatUrl" class="link-url">{{ tgStatUrl }}</a>
          </div>
        </div>
      </div>
    </div>

    <div class="pricing-section">
      <h2 class="pricing-title">Реклама:</h2>
      <div class="pricing-items">
        <div
          v-for="(label, idx) in pricingLabels"
          :key="idx"
          class="pricing-item"
        >
          <span class="pricing-label">{{ label }}:</span>
          <span class="pricing-value">{{ formatPrice(idx) }} ₽</span>
        </div>
      </div>
      <button class="action-btn primary" @click="showPopup = true">
        Купить рекламу
      </button>
    </div>

    <!-- Попап -->
    <div v-if="showPopup" class="popup-backdrop" @click.self="showPopup = false">
      <div class="popup">
        <h3>Купить рекламу</h3>
        <form @submit.prevent="buyAd">
          <label>
            Тип рекламы:
            <select v-model.number="form.ad_type_id" required>
              <option value="" disabled selected>Выберите тип</option>
              <option
                v-for="t in filteredAdTypes"
                :key="t.id"
                :value="t.id"
              >{{ t.top_duration_in_hours }}/{{ t.duration_in_hours }}</option>
            </select>
          </label>

          <label>
            ID сообщения:
            <input
              type="number"
              v-model.number="form.message_id"
              required
              placeholder="Напишите пост боту и вставьте ID"
            />
          </label>

          <label>
            Время публикации:
            <select v-model="form.placement_date" required>
              <option disabled selected value="">Выберите дату и час</option>
              <option
                v-for="dt in availableDates"
                :key="dt"
                :value="dt"
              >
                {{ formatDateTime(dt) }}
              </option>
            </select>
          </label>

          <button type="submit" class="action-btn primary">Купить</button>
          <button type="button" class="action-btn secondary" @click="showPopup = false">Отмена</button>
        </form>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, onMounted } from 'vue'
import { useAppStore } from '@/stores/app'
import { useRoute } from 'vue-router'

const appStore = useAppStore()
const route = useRoute()
const groupId = Number(route.params.id)

const group = reactive({ username: '', subject_ids: [], country_id: null, language_id: null, ad_prices: {} })
const subjectsList = ref([])
const countries = ref([])
const languages = ref([])
const adTypes = ref([])
const availableDates = ref([])

const pricingLabels = ['Пост', 'Закреплённый пост', 'Упоминание']

const showPopup = ref(false)
const form = reactive({
  ad_type_id: null,
  message_id: null,
  placement_date: ''
})

const headers = () => ({
  'Content-Type': 'application/json',
  Authorization: 'Telegram-Init-Data ' + appStore.tgInitDataRow
})

async function fetchSubjects() {
  const res = await fetch(`${appStore.apiBaseUrl}/api/tables/subjects`, { headers: headers(), mode: 'cors' })
  subjectsList.value = await res.json()
}
async function fetchCountries() {
  const res = await fetch(`${appStore.apiBaseUrl}/api/tables/countries`, { headers: headers(), mode: 'cors' })
  countries.value = await res.json()
}
async function fetchLanguages() {
  const res = await fetch(`${appStore.apiBaseUrl}/api/tables/languages`, { headers: headers(), mode: 'cors' })
  languages.value = await res.json()
}
async function fetchAdTypes() {
  const res = await fetch(`${appStore.apiBaseUrl}/api/tables/ad_types`, { headers: headers(), mode: 'cors' })
  adTypes.value = await res.json()
}
async function fetchGroup() {
  const res = await fetch(`${appStore.apiBaseUrl}/api/group/${groupId}`, { headers: headers(), mode: 'cors' })
  const data = await res.json()
  Object.assign(group, data)
  availableDates.value = data.available_dates || []
}

const subjectNames = computed(() =>
  group.subject_ids.map(id => subjectsList.value.find(s => s.id === id)?.name || id).join(' / ')
)
const countryName = computed(() =>
  countries.value.find(c => c.id === group.country_id)?.name || '—'
)
const languageName = computed(() =>
  languages.value.find(l => l.id === group.language_id)?.name || '—'
)

const filteredAdTypes = computed(() =>
  adTypes.value.filter(t => t.id in group.ad_prices)
)

const tgUrl = computed(() => `https://t.me/${group.username}`)
const tgStatUrl = computed(() => `https://tgstat.com/channel/@${group.username}`)

function formatPrice(idx) {
  const key = Object.keys(group.ad_prices)[idx]
  return group.ad_prices[key] || 0
}

function formatDateTime(iso) {
  const d = new Date(iso)
  return d.toLocaleString('ru-RU', {
    day: 'numeric', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  })
}

async function buyAd() {
  try {
    await fetch(
      `${appStore.apiBaseUrl}/api/group/${groupId}/buy`,
      {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({
          ad_type_id: form.ad_type_id,
          message_id: form.message_id,
          placement_date: form.placement_date
        }),
        mode: 'cors'
      }
    )
    alert('Реклама куплена!')
    appStore.balance -= amount.value
    showPopup.value = false
  } catch (e) {
    console.error('Ошибка покупки рекламы:', e)
  }
}

onMounted(async () => {
  await appStore.initTelegram()
  await Promise.all([
    fetchSubjects(),
    fetchCountries(),
    fetchLanguages(),
    fetchAdTypes(),
    fetchGroup()
  ])
})
</script>

<style>
/* Попап */
.popup-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.4);
  display: flex;
  align-items: center;
  justify-content: center;
}
.popup {
  background: white;
  padding: 20px;
  border-radius: 8px;
  width: 280px;
}
.popup h3 {
  margin-top: 0;
  margin-bottom: 12px;
}
.popup form label {
  display: block;
  margin-bottom: 10px;
  font-size: 14px;
}
.popup form select,
.popup form input {
  width: 100%;
  padding: 6px;
  margin-top: 4px;
  box-sizing: border-box;
}
.popup form .action-btn {
  width: 48%;
  margin-right: 4%;
}
.popup form .action-btn:last-child {
  margin-right: 0;
}
/* Стили существующие (необходимые) */
.pricing-section .action-btn {
  margin-top: 12px;
}
</style>
